using System;
using System.Collections.Generic;
using System.Linq;
using Emby.Server.Implementations.Plugins;
using MediaBrowser.Model.Plugins;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;

namespace Emby.Server.Implementations.Plugins.Tests
{
    public class PluginManagerTests
    {
        private class TestLocalPlugin : LocalPlugin
        {
            public TestLocalPlugin(string id, Version version, PluginStatus status, bool isEnabledAndSupported)
            {
                Id = id;
                Version = version;
                Manifest = new PluginManifest { Status = status, AutoUpdate = true };
                IsEnabledAndSupported = isEnabledAndSupported;
                Name = $"Plugin-{id}";
            }

            public override string Id { get; }
            public override Version Version { get; }
            public override PluginManifest Manifest { get; }
            public override bool IsEnabledAndSupported { get; }
            public override string Name { get; }
            public override IReadOnlyList<string> DllFiles => Array.Empty<string>();
            public override string Path => "";

            // We need to override ChangePluginState to simulate failure for testing logging
            public bool ChangePluginStateReturnValue { get; set; } = true;

            public override bool ChangePluginState(PluginStatus status)
            {
                return ChangePluginStateReturnValue;
            }
        }

        private class TestPluginManager : PluginManager
        {
            public TestPluginManager(ILogger<PluginManager> logger)
                : base(logger, null!, null!, "", new Version(1, 0))
            {
                // Override _plugins list with test plugins
                _plugins = new List<LocalPlugin>();
            }

            public new List<LocalPlugin> _plugins;

            // Expose ProcessAlternative for testing
            public void CallProcessAlternative(LocalPlugin plugin)
            {
                // Call private method via reflection
                var method = typeof(PluginManager).GetMethod("ProcessAlternative", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
                method.Invoke(this, new object[] { plugin });
            }

            // Override ChangePluginState to call LocalPlugin's ChangePluginState
            protected override bool ChangePluginState(LocalPlugin plugin, PluginStatus status)
            {
                if (plugin is TestLocalPlugin testPlugin)
                {
                    return testPlugin.ChangePluginState(status);
                }
                return base.ChangePluginState(plugin, status);
            }
        }

        [Fact]
        public void ProcessAlternative_LogsError_When_ChangePluginStateFails_ActiveStatus()
        {
            // Arrange
            var loggerMock = new Mock<ILogger<PluginManager>>();
            var manager = new TestPluginManager(loggerMock.Object);

            var previousPlugin = new TestLocalPlugin("plugin1", new Version(1, 0), PluginStatus.Active, true);
            var currentPlugin = new TestLocalPlugin("plugin1", new Version(2, 0), PluginStatus.Active, true);

            // Add previous plugin to manager's plugins list
            manager._plugins.Add(previousPlugin);

            // Simulate ChangePluginState failure for previous version
            previousPlugin.ChangePluginStateReturnValue = false;

            // Act
            manager.CallProcessAlternative(currentPlugin);

            // Assert
            loggerMock.Verify(
                x => x.Log(
                    LogLevel.Error,
                    It.IsAny<EventId>(),
                    It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("Unable to enable version")),
                    null,
                    It.IsAny<Func<It.IsAnyType, Exception, string>>()),
                Times.Once);
        }

        [Fact]
        public void ProcessAlternative_LogsError_When_ChangePluginStateFails_SupersededStatus()
        {
            // Arrange
            var loggerMock = new Mock<ILogger<PluginManager>>();
            var manager = new TestPluginManager(loggerMock.Object);

            var previousPlugin = new TestLocalPlugin("plugin1", new Version(1, 0), PluginStatus.Active, true);
            var currentPlugin = new TestLocalPlugin("plugin1", new Version(2, 0), PluginStatus.Superseded, true);

            // Add previous plugin to manager's plugins list
            manager._plugins.Add(previousPlugin);

            // Simulate ChangePluginState failure for previous version
            previousPlugin.ChangePluginStateReturnValue = false;

            // Act
            manager.CallProcessAlternative(currentPlugin);

            // Assert
            loggerMock.Verify(
                x => x.Log(
                    LogLevel.Error,
                    It.IsAny<EventId>(),
                    It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("Unable to supercede version")),
                    null,
                    It.IsAny<Func<It.IsAnyType, Exception, string>>()),
                Times.Once);
        }
    }

    // Minimal stubs for LocalPlugin and PluginManifest to compile
    public abstract class LocalPlugin
    {
        public abstract string Id { get; }
        public abstract Version Version { get; }
        public abstract PluginManifest Manifest { get; }
        public abstract bool IsEnabledAndSupported { get; }
        public abstract string Name { get; }
        public abstract IReadOnlyList<string> DllFiles { get; }
        public abstract string Path { get; }
        public virtual bool ChangePluginState(PluginStatus status) => true;
    }

    public class PluginManifest
    {
        public PluginStatus Status { get; set; }
        public bool AutoUpdate { get; set; }
    }
}
